ALTER TABLE public.support_replies ADD COLUMN IF NOT EXISTS message_kind text NOT NULL DEFAULT 'message' CHECK (message_kind IN ('message', 'resolution'));
CREATE OR REPLACE FUNCTION public.admin_update_bug_report_type(p_report_id uuid, p_ticket_type text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT is_admin_user() THEN RAISE EXCEPTION 'Forbidden'; END IF; IF p_ticket_type NOT IN ('bug', 'suggestion', 'usage_help', 'account_security', 'suspension_appeal', 'deletion_recovery') THEN RAISE EXCEPTION 'Invalid ticket type'; END IF; UPDATE bug_reports SET ticket_type = p_ticket_type, updated_at = now() WHERE id = p_report_id; IF NOT FOUND THEN RAISE EXCEPTION 'Report not found'; END IF; END; $$;
CREATE OR REPLACE FUNCTION public.admin_close_bug_report(p_report_id uuid, p_result text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE target_user uuid; report_title text; old_status text; BEGIN IF NOT is_admin_user() THEN RAISE EXCEPTION 'Forbidden'; END IF; IF char_length(trim(p_result)) = 0 THEN RAISE EXCEPTION 'Resolution cannot be empty'; END IF; SELECT user_id, title, status INTO target_user, report_title, old_status FROM bug_reports WHERE id = p_report_id FOR UPDATE; IF target_user IS NULL THEN RAISE EXCEPTION 'Report not found'; END IF; IF old_status = 'closed' THEN RAISE EXCEPTION 'Ticket is already closed'; END IF; INSERT INTO support_replies(report_id, author_id, body, message_kind) VALUES (p_report_id, auth.uid(), trim(p_result), 'resolution'); UPDATE bug_reports SET status = 'closed', updated_at = now() WHERE id = p_report_id; INSERT INTO bug_report_events(report_id, actor_id, event_type, previous_status, next_status) VALUES (p_report_id, auth.uid(), 'status_changed', old_status, 'closed'); INSERT INTO site_notifications(title, content, content_type, delivery_type, recipient_user_id, related_ticket_id, created_by) VALUES ('人工客服咨询已结束：' || report_title, '客服已完成处理。点击查看系统结果与管理员处理说明。', 'markdown', 'message', target_user, p_report_id, auth.uid()); END; $$;
GRANT EXECUTE ON FUNCTION public.admin_update_bug_report_type(uuid, text) TO authenticated;
